"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7866],{5168(e){e.exports=JSON.parse('{"title":"\uc131\ub2a5 \ucd5c\uc801\ud654 \uae30\uc220\uc740 \uc0ac\uc6a9\ud558\uba74 \ub05d\uc77c\uae4c","date":"2025-01-31","coverUrl":"/kudzu-based-bench/assets/notion/bf849a09ce513df0.png","html":"<h2 data-notion-block-id=\\"18ce548d-8a8e-80cb-9049-f055f0e1e3f0\\" id=\\"18ce548d-8a8e-80cb-9049-f055f0e1e3f0\\">\uc131\ub2a5 \ucd5c\uc801\ud654 \uae30\uc220\uc740 \uc0ac\uc6a9\ud558\uba74 \ub05d\uc77c\uae4c</h2><a href=\\"https://www.youtube.com/watch?v=j5E_U_hu7g0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=j5E_U_hu7g0</a><p data-notion-block-id=\\"18ce548d-8a8e-80d0-a13e-f5c6df788e17\\">\uc5ec\ub7ec\uac00\uc9c0 \uc131\ub2a5 \ucd5c\uc801\ud654 \ud560 \uc218 \uc788\ub294\ub370 \ub193\uce60 \uc218 \uc788\ub294 \ubd80\ubd84\uc774\ub098, \uc544\ub2c8\uba74 \uc798\ubabb \uc0ac\uc6a9\ud574\uc11c \uc624\ud788\ub824 \uc131\ub2a5\uc744 \ub290\ub9ac\uac8c \ud558\uac70\ub098 \ucd5c\uc801\ud654 \ud558\uc9c0 \ubabb\ud55c \uacbd\uc6b0\ub97c \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \ud2b9\ud788 \ucd08\ubc18\uc5d0 \uc18c\uac1c\ud558\ub294 Lazy Loading API\ub098 <a href=\\"https://developer.mozilla.org/en-US/docs/Web/Performance/Speculative_loading\\">Speculative loading</a>\uad00\ub828 \ubb38\uc81c\uac00 \ub9ce\uc774 \uc0dd\uae38 \uc218 \uc788\uc73c\ub2c8, \uc870\uc2ec\ud574\uc11c \uc798 \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-80e2-ae2c-f270938a7988\\" id=\\"18ce548d-8a8e-80e2-ae2c-f270938a7988\\">Streaming SSR\uc758 \ub4b7\uba74</h2><a href=\\"https://gitnation.com/contents/out-of-order-streaming-the-secret-powering-modern-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/out-of-order-streaming-the-secret-powering-modern-react</a><p data-notion-block-id=\\"18ce548d-8a8e-80db-ba58-e732fd6316ac\\">Streaming SSR\uc774 HTML Streaming\uacfc JS\ub97c \ud1b5\ud574\uc11c \uc5b4\ub5bb\uac8c \uad6c\ud604\ub418\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \uae4a\uac8c \ud30c\uace0\ub4e4\uc9c0 \uc54a\uace0, \ub77c\uc774\ube0c \ucf54\ub529\uc744 \ud1b5\ud574 \uc5b4\ub5bb\uac8c \uad6c\ud604\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ubbc0\ub85c, \uac04\ub2e8\ud558\uac8c <code>&#x3C;Suspense></code>\uc548\uc758 Server Components\uac00 \uc5b4\ub5bb\uac8c \uc81c\uc790\ub9ac\ub85c \ub4e4\uc5b4\uac00\ub294\uc9c0 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-80bb-bb46-da648ec954d4\\" id=\\"18ce548d-8a8e-80bb-bb46-da648ec954d4\\">Server Functions\uc640 \ub450 \uad00\uc810</h2><a href=\\"https://www.brenelz.com/posts/why-server-functions-matter-in-a-server-component-world/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.brenelz.com/posts/why-server-functions-matter-in-a-server-component-world/</a><p data-notion-block-id=\\"18ce548d-8a8e-8043-b306-dacda0e92c8a\\">Tanstack Start\uc5d0\uc11c <a href=\\"https://tanstack.com/start/latest/docs/framework/react/server-functions\\">Server Functions \uae30\ub2a5\uc744 \ucd9c\uc2dc</a>\ud588\uc2b5\ub2c8\ub2e4. Tanstack Start\uc758 Server Functions \uac1c\ub150\uacfc RSC(\uc0ac\uc2e4\uc0c1 \ud604\uc7ac\ub294 Next.js)\uc758 Server Functions\ub294 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0, \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc744 \uac00\uc9c0\uace0 \uc788\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c Server Functions\uc5d0 \uad00\uc2ec\uc774 \uc0dd\uacbc\ub2e4\uba74 \uc774\uc5b4\uc11c <a href=\\"https://www.brenelz.com/posts/server-function-benefits/\\">Server Functions\uc758 \uc7a5\uc810</a> \uae00\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-807d-9296-d06df91d2f67\\" id=\\"18ce548d-8a8e-807d-9296-d06df91d2f67\\">\ucd08\uae30 \ub85c\ub4dc \uc131\ub2a5 \ucd5c\uc801\ud654 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://www.developerway.com/posts/initial-load-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.developerway.com/posts/initial-load-performance</a><p data-notion-block-id=\\"18ce548d-8a8e-8048-a95d-c89f61ea59ec\\">\ucd08\uae30 \ub85c\ub4dc \uc131\ub2a5 \ucd5c\uc801\ud654\uc758 \ubaa8\ub4e0 \uac83\uc5d0 \ub300\ud55c \uae00\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ucd08\uae30 \ub85c\ub4dc\uc5d0 \uad00\ud55c \uc9c0\ud45c(LCP, FCP), \uce21\uc815 \ubc29\uc2dd, \uac04\ub2e8\ud55c \ud574\uacb0\ucc45\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uce5c\uc808\ud558\uac8c \uc124\uba85\ud558\ubbc0\ub85c, \uac04\ub2e8\ud558\uac8c \uc54c\uc544\ubcf4\uae30\uc5d0 \uc88b\uc2b5\ub2c8\ub2e4. \uc774\uc804\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/15ee548d-8a8e-80b5-9d6e-cfa07648afc4#162e548d-8a8e-80d4-bb42-c4874b71f3bf\\">\ube0c\ub77c\uc6b0\uc800 \uce90\uc2f1\uc758 \uc885\ub958, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ub2e4\ub904\uc57c \ud560\uae4c</a>\uc5d0\uc11c \ub354 \uc5ec\ub7ec \ubc29\uc2dd\uc744 \ub2e4\ub8e8\ubbc0\ub85c, \ubcf4\uc2dc\uba74 \ub354 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-8013-a5e7-eb8580b4bb48\\" id=\\"18ce548d-8a8e-8013-a5e7-eb8580b4bb48\\">React 19\uc5d0\uc11c Optimistic update Form \ub9cc\ub4e4\uae30</h2><a href=\\"https://rdrn.me/react-forms/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rdrn.me/react-forms/</a><p data-notion-block-id=\\"18ce548d-8a8e-80c1-9056-f36d1e02f3b9\\">React 19\uc5d0\uc11c \ucd94\uac00\ub41c <code>useActionState</code>, <code>useOptimistic</code>\uacfc Server Components\uc73c\ub85c \ud074\ub77c\uc774\uc5b8\ud2b8/\uc11c\ubc84 \uc720\ud6a8\uc131 \uac80\uc0ac, \ub099\uad00\uc801 \uc5c5\ub370\uc774\ud2b8\ub97c \uad6c\ud604\ud574\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-80f2-acea-e72ab5566a37\\" id=\\"18ce548d-8a8e-80f2-acea-e72ab5566a37\\">Runtime CSS-in-JS\uc640 XSS \uc704\ud5d8\uc131</h2><a href=\\"https://andrei-calazans.com/posts/styled-components-xss-danger/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://andrei-calazans.com/posts/styled-components-xss-danger/</a><p data-notion-block-id=\\"18ce548d-8a8e-80b7-aba5-e835e55c7e4e\\">Runtime CSS-in-JS\uc5d0\uc11c XSS\uac00 \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \uc9c0\uc810\uacfc \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-80d3-b26f-dfc1d1104bbc\\" id=\\"18ce548d-8a8e-80d3-b26f-dfc1d1104bbc\\">Relay\uc640 Vite, \uadf8\ub9ac\uace0 SSR</h2><a href=\\"https://aqora.io/blog/implementing-streaming-ssr-with-react-relay-and-vite-899908\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aqora.io/blog/implementing-streaming-ssr-with-react-relay-and-vite-899908</a><p data-notion-block-id=\\"18ce548d-8a8e-8087-820e-c0718e187205\\">SSR\uc744 \uae30\uc874 Relay + React router \ud658\uacbd\uc5d0\uc11c \ucee4\uc2a4\ud140 \uc124\uc815\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-8081-9be6-e2896d781c8b\\" id=\\"18ce548d-8a8e-8081-9be6-e2896d781c8b\\">\ub124\uc774\ud2f0\ube0c\ub85c <code>&#x3C;Portal></code>\ub300\uccb4\ud558\uae30</h2><a href=\\"https://fullystacked.net/portal/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fullystacked.net/portal/</a><p data-notion-block-id=\\"18ce548d-8a8e-80fc-91a1-eeff813535c2\\">\uc544\uc9c1 \ubaa8\ub4e0 \uc8fc\uc694 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc9c0\uc6d0\ud558\uc9c0 \uc54a\uc9c0\ub9cc, <code>&#x3C;dialog></code>, Popover API, Anchor positioning API\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-803e-9f15-c421e980f228\\" id=\\"18ce548d-8a8e-803e-9f15-c421e980f228\\">\ud55c\ubc88 \ucbe4 \ubcfc\ub9cc\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac</h2><a href=\\"https://github.com/aidenybai/react-scan\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/aidenybai/react-scan</a><p data-notion-block-id=\\"18ce548d-8a8e-80c1-963d-ce54b2aa45e8\\">React \uc131\ub2a5 \uc774\uc288\ub97c \ud0d0\uc9c0\ud558\uae30 \uc27d\uac8c \ubcf4\uc5ec\uc8fc\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. \uc774\uc804 \ub9ac\uc561\ud2b8 \uc131\ub2a5 \uce21\uc815 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640 \ube44\uad50\ud574\uc11c \uc5b4\ub5a4 \ubd80\ubd84\uc744 \ud574\uacb0\ud588\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uac83\uc774 \uc778\uc0c1\uc801\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"18ce548d-8a8e-80eb-9c23-f04f042f4801\\" id=\\"18ce548d-8a8e-80eb-9c23-f04f042f4801\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://reactnative.dev/blog/2025/01/21/version-0.77\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/blog/2025/01/21/version-0.77</a><a href=\\"https://developer.chrome.com/blog/movebefore-api\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/movebefore-api</a><p data-notion-block-id=\\"184e548d-8a8e-806a-ac09-e8eaeeb138ca\\">\ub2e4\uc591\ud55c CSS\ub97c \uc9c0\uc6d0\ud558\ub294 React Native 0.77 \ubc84\uc804 \ucd9c\uc2dc, DOM API\uc744 \ud1b5\ud574 DOM\uc744 \ub2e4\ub978 DOM\uc73c\ub85c \uc62e\uaca8\uc57c \ud560 \ub54c DOM\uc5d0 \ub2f4\uaca8\uc788\ub294 \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud560 \uc218 \uc788\ub294 <code>moveBefore()</code>\uc18c\uac1c \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);